// Define RedisClient interface for Edge compatibility
interface RedisClient {
    get(key: string): Promise<string | null>;
    setex(key: string, ttl: number, value: string): Promise<string>;
}

// Configuration Constants
const MAX_LOCAL_CACHE_ENTRIES: number = 1000;
const DEFAULT_TTL_SECONDS: number = 60;

// Local Cache Store (Map preserves insertion order, useful for LRU)
const localCache = new Map<string, { data: any, timestamp: number }>();

// Placeholder for Redis Client instance (replace with actual client in production)
const redisClient: RedisClient = {
    async get(key: string): Promise<string | null> { return null; },
    async setex(key: string, ttl: number, value: string): Promise<string> { return 'OK'; },
};

/**
 * Internal function to set data in local and/or Redis cache.
 * Implements LRU eviction for local cache.
 */
async function cacheSetInternal(
    key: string,
    data: any,
    ttlSeconds: number | undefined,
    target: 'localOnly' | 'redisOnly' | 'all'
): Promise<void> {
    const effectiveTtl = ttlSeconds || DEFAULT_TTL_SECONDS;

    if (target.includes('local') || target === 'all') {
        if (localCache.size >= MAX_LOCAL_CACHE_ENTRIES) {
            const oldestKey = localCache.keys().next().value;
            if (oldestKey) localCache.delete(oldestKey); // LRU eviction
        }
        localCache.set(key, { data, timestamp: Date.now() });
    }

    if (target.includes('redis') || target === 'all') {
        try {
            await redisClient.setex(key, effectiveTtl, JSON.stringify(data));
        } catch (e) { /* Error handling for Redis set, e.g., logging */ }
    }
}

/**
 * Asynchronously revalidates a cache entry by fetching fresh data from the origin
 * and updating all relevant caches.
 */
async function revalidateInBackground(
    key: string,
    fetcher: () => Promise<any>,
    ttlSeconds: number | undefined
): Promise<void> {
    try {
        const newData = await fetcher();
        await cacheSetInternal(key, newData, ttlSeconds, 'all');
    } catch (e) { /* Error handling for background revalidation, e.g., logging */ }
}

/**
 * Implements an SWR (Stale-While-Revalidate) caching strategy.
 * Checks local cache, then Redis cache, then fetches from origin.
 * Triggers background revalidation when serving stale or Redis-sourced data.
 */
async function getOrSetCache<T>(
    key: string,
    fetcher: () => Promise<T>,
    ttlSeconds?: number
): Promise<T> {
    const effectiveTtl = ttlSeconds || DEFAULT_TTL_SECONDS;

    // 1. Local Cache Check
    if (localCache.has(key)) {
        const entry = localCache.get(key)!;
        const expiryTime = entry.timestamp + effectiveTtl * 1000;

        if (Date.now() < expiryTime) {
            return entry.data as T; // Return fresh local data
        } else {
            revalidateInBackground(key, fetcher, ttlSeconds); // Trigger background revalidation
            return entry.data as T; // Return stale local data
        }
    }

    // 2. Redis Cache Check
    let redisData: string | null = null;
    try {
        redisData = await redisClient.get(key);
    } catch (e) { /* Error handling for Redis get, continue to origin on failure */ }

    if (redisData !== null) {
        try {
            const parsedData = JSON.parse(redisData) as T;
            await cacheSetInternal(key, parsedData, ttlSeconds, 'localOnly'); // Populate local cache
            revalidateInBackground(key, fetcher, ttlSeconds); // Trigger background revalidation for potentially stale Redis data
            return parsedData;
        } catch (e) { /* Error handling for parsing Redis data, fall through to origin */ }
    }

    // 3. Origin Fetch (Cache Miss)
    const fetchedData = await fetcher();
    await cacheSetInternal(key, fetchedData, ttlSeconds, 'all'); // Cache fetched data
    return fetchedData;
}
